import {esc,csv,parseCSV,normalizeRows} from '../agent/core.mjs';
export {esc};
export const num=(v,d=2)=>v===null||v===undefined||!Number.isFinite(Number(v))?'—':Number(v).toLocaleString('zh-CN',{maximumFractionDigits:d,minimumFractionDigits:d});
export function download(name,text,type='text/plain;charset=utf-8'){const u=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
export function downloadRows(name,rows){if(!rows.length)throw Error('暂无可下载数据');download(name,csv(rows),'text/csv;charset=utf-8');}
export async function readFile(file){if(!file)throw Error('请选择文件');if(file.size>5*1024*1024)throw Error('轻量入口限制5MB，请按井或时间段抽样');const text=await file.text();const rows=file.name.toLowerCase().endsWith('.json')?JSON.parse(text):parseCSV(text);if(!Array.isArray(rows)||!rows.length)throw Error('文件必须包含非空记录数组或带表头的CSV');if(rows.length>30000)throw Error('单批上限30000行，请拆分数据');return normalizeRows(rows);}
export function table(rows,columns,limit=20){return `<div class="data-table"><table><thead><tr>${columns.map(([k,n])=>`<th>${esc(n)}</th>`).join('')}</tr></thead><tbody>${rows.slice(0,limit).map(r=>`<tr>${columns.map(([k,n,d])=>`<td>${typeof r[k]==='number'?num(r[k],d??3):esc(r[k]??'—')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
export function panel(title,body,extra='',note=''){return `<section class="panel"><div class="panel-head"><h2>${title}</h2>${extra}</div><div class="panel-body">${body}</div>${note?`<div class="panel-note">${note}</div>`:''}</section>`;}
export const flow=steps=>`<div class="flow">${steps.map((s,i)=>`${i?'<span class="arrow">→</span>':''}<span class="step">${esc(s)}</span>`).join('')}</div>`;
export function chart(series,{unit='',label='日期 / 序列',height=225,zero=false}={}){const valid=series.flatMap(s=>s.values.filter(v=>v!==null&&v!==undefined&&Number.isFinite(Number(v))).map(Number));if(!valid.length)return '<div class="empty">计算后展示曲线与真实评价结果</div>';let lo=zero?0:Math.min(...valid),hi=Math.max(...valid);if(hi===lo){hi+=1;lo-=1;}const pad=(hi-lo)*.12;lo-=pad;hi+=pad;const w=650,h=height,left=58,right=18,top=22,bottom=36,n=Math.max(...series.map(s=>s.values.length)),x=i=>left+i/Math.max(1,n-1)*(w-left-right),y=v=>top+(hi-v)/(hi-lo)*(h-top-bottom);return `<div class="chart-box"><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(series.map(s=>s.name).join('与'))}；单位${esc(unit)}">${Array.from({length:5},(_,i)=>{const v=lo+(hi-lo)*i/4;return `<line x1="${left}" x2="${w-right}" y1="${y(v)}" y2="${y(v)}" stroke="#ece8e1"/><text x="${left-8}" y="${y(v)+4}" text-anchor="end">${num(v,hi-lo<2?2:0)}</text>`;}).join('')}<text x="${left}" y="11">${esc(unit)}</text>${series.map(s=>{let path='',active=false;for(let i=0;i<s.values.length;i++){const v=s.values[i];if(v===null||v===undefined||!Number.isFinite(Number(v))){active=false;continue;}path+=`${active?'L':'M'}${x(i).toFixed(1)},${y(v).toFixed(1)} `;active=true;}return `<path d="${path}" fill="none" stroke="${s.color??'#ac2834'}" stroke-width="2" ${s.dash?'stroke-dasharray="6 4"':''}/>`;}).join('')}${[0,Math.floor((n-1)/2),n-1].map(i=>`<text x="${x(i)}" y="${h-14}" text-anchor="middle">${esc(series[0].labels?.[i]??String(i+1))}</text>`).join('')}</svg><div class="legend">${series.map(s=>`<span><i class="${s.dash?'dashed':''}" style="background:${s.color??'#ac2834'};color:${s.color??'#ac2834'}"></i>${esc(s.name)}${s.dash?'（虚线）':'（实线）'}</span>`).join('')}</div><div class="unit-note">横轴：${esc(label)}；纵轴：${esc(unit)}。缺失值断线显示。</div></div>`;}
export function field(id,title,value,step=1){return `<label>${title}<input id="${id}" type="number" value="${value}" step="${step}"></label>`;}
